//! 🛂️ Exact forwarded allocation admission retains the original receiving owner.
use crate::native_encoding::{NativeEncodeControl,NativeAllocationRequest,NativeForwardedEncodeControl};
use crate::{ValueError,ValueRefusalKind};
use std::sync::atomic::{AtomicUsize,Ordering};
use crate::eff;
fn fixture()->serde_json::Value{serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🛂️allocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
#[test]
fn forwarded_allocation_precedes_every_small_owned_span_and_retains_the_same_authority(){
 let neutral=fixture();let law=&neutral["ownership"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;
 let prior:Vec<u8>=serde_json::from_value(law["prior"].clone()).unwrap();let text=law["text"].as_str().unwrap();let pointer=text.as_ptr();let calls=AtomicUsize::new(0);
 let mut host_progress=|_|true;let mut host_receipt=Some(NativeEncodeControl::new(ceiling,&mut host_progress).pause().unwrap());
 {let allocate=|event:crate::native_encoding::NativeAllocationEvent|{let request=match event{crate::native_encoding::NativeAllocationEvent::Quote(request)=>request,_=>return Ok(())};let mut host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(request.owned_bytes,host.owned_bytes());assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);assert_eq!(request.maximum_bytes,ceiling);calls.fetch_add(1,Ordering::Relaxed);let result=host.charge(request.bytes);host_receipt=Some(host.pause().unwrap());result};
 let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(allocate));authority.with_send_loan(&mut (),|allocate_loan|{let mut guest=NativeEncodeControl::new_forwarded(ceiling,&mut progress,allocate_loan);
 let mut copied=eff::reserve_bytes(&mut guest,prior.len()).unwrap();copied.extend_from_slice(&prior);let mut output=eff::reserve_text(&mut guest,text.len()).unwrap();output.push_str(text);assert_eq!(calls.load(Ordering::Relaxed),2);assert_eq!(copied,prior);assert_eq!(serde_json::to_string(&output).unwrap(),serde_json::to_string(text).unwrap());
 let receipt=guest.pause().ok().unwrap();let mut next_progress=|_|true;let mut resumed=NativeForwardedEncodeControl::resume(receipt,&mut next_progress).ok().unwrap();
 let tail=law["tail"].as_str().unwrap();let mut grown=eff::reserve_text(&mut resumed,tail.len()).unwrap();grown.push_str(tail);assert_eq!(grown,"x");assert_eq!(resumed.owned_bytes(),law["expected"].as_u64().unwrap()as usize);assert_eq!(calls.load(Ordering::Relaxed),3);assert_eq!(text.as_ptr(),pointer);
 drop(resumed);}).unwrap();assert!(authority.into_port().is_ok());}
 let host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(host.owned_bytes(),law["expected"].as_u64().unwrap()as usize);
 #[cfg(not(target_arch="wasm32"))]{fn assert_send<T:Send>(){}assert_send::<crate::native_encoding::NativeForwardedEncodeContinuation<'static>>();}
}
#[test]
fn forwarded_allocation_refuses_before_reserving_storage_and_preserves_the_original_ledger(){
 let neutral=fixture();let bytes=neutral["refusedBytes"].as_u64().unwrap()as usize;let source="x".repeat(bytes);let pointer=source.as_ptr();
 for kind in [ValueRefusalKind::OwnershipLimit,ValueRefusalKind::Canceled]{let calls=AtomicUsize::new(0);let allocate=|event:crate::native_encoding::NativeAllocationEvent|{let request=match event{crate::native_encoding::NativeAllocationEvent::Quote(request)=>request,_=>return Ok(())};calls.fetch_add(1,Ordering::Relaxed);assert_eq!(request.owned_bytes,0);assert_eq!(request.bytes,bytes);Err(ValueError::literal(kind,"original receiving authority refused allocation"))};let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(allocate));authority.with_send_loan(&mut (),|allocate_loan|{let mut control=NativeEncodeControl::new_forwarded(bytes,&mut progress,allocate_loan);let error=eff::reserve_text(&mut control,source.len()).unwrap_err();assert_eq!(error.kind,kind);assert_eq!(control.owned_bytes(),0);assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(source.as_ptr(),pointer);}).unwrap();assert!(authority.into_port().is_ok());}
 let calls=AtomicUsize::new(0);let allocate=|event:crate::native_encoding::NativeAllocationEvent|{if !matches!(event,crate::native_encoding::NativeAllocationEvent::Quote(_)){return Ok(())}calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(allocate));authority.with_send_loan(&mut (),|allocate_loan|{let mut zero=NativeEncodeControl::new_forwarded(0,&mut progress,allocate_loan);assert_eq!(eff::reserve_text(&mut zero,source.len()).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(calls.load(Ordering::Relaxed),0);assert_eq!(zero.owned_bytes(),0);}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn retained_forwarded_hops_keep_the_original_receipt_on_work_and_allocation_refusal(){
 use std::sync::atomic::AtomicBool;
 let neutral=fixture();let law=&neutral["hops"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;let bytes:Vec<u8>=serde_json::from_value(law["nextBytes"].clone()).unwrap();let allowed=AtomicBool::new(true);let calls=AtomicUsize::new(0);
 let mut host_progress=|_|true;let mut host_receipt=Some(NativeEncodeControl::new(ceiling,&mut host_progress).pause().unwrap());
 {let allocate=|event:crate::native_encoding::NativeAllocationEvent|{let request=match event{crate::native_encoding::NativeAllocationEvent::Quote(request)=>request,_=>return Ok(())};calls.fetch_add(1,Ordering::Relaxed);if !allowed.load(Ordering::Relaxed){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original retained receiving lifetime closed"))}let mut host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(host.owned_bytes(),request.owned_bytes);let result=host.charge(request.bytes);host_receipt=Some(host.pause().unwrap());result};
 let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(allocate));authority.with_send_loan(&mut (),|allocate_loan|{let mut receipt=NativeEncodeControl::new_forwarded(ceiling,&mut progress,allocate_loan).pause().ok().unwrap();
 let mut first=|_|true;let error=receipt.encode(&mut first,|control|{eff::reserve_bytes(control,law["firstCharge"].as_u64().unwrap()as usize)?;control.begin_stage(law["declaredWork"].as_u64().unwrap()as usize)?;control.advance(law["refusedWork"].as_u64().unwrap()as usize)}).map_err(eff::cause).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!(receipt.owned_bytes(),3);
 allowed.store(false,Ordering::Relaxed);let mut next=|_|true;assert_eq!(receipt.encode(&mut next,|control|{let mut owned=eff::reserve_bytes(control,bytes.len())?;owned.extend_from_slice(&bytes);Ok::<_,ValueError>(owned)}).map_err(eff::cause).unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),3);assert_eq!(receipt.maximum_bytes(),ceiling);
 allowed.store(true,Ordering::Relaxed);let mut final_progress=|_|true;assert_eq!(receipt.encode(&mut final_progress,|control|{let mut owned=eff::reserve_bytes(control,bytes.len())?;owned.extend_from_slice(&bytes);Ok::<_,ValueError>(owned)}).unwrap(),bytes);assert_eq!(receipt.owned_bytes(),law["expected"].as_u64().unwrap()as usize);assert_eq!(calls.load(Ordering::Relaxed),3);drop(receipt);}).unwrap();assert!(authority.into_port().is_ok());}
 let host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(host.owned_bytes(),5);
}

#[test]
fn direct_original_port_receipt_composes_short_observers_without_resetting_admission(){
 let neutral=fixture();let law=&neutral["observer"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;let text=law["text"].as_str().unwrap();let calls=AtomicUsize::new(0);let original_progress=AtomicUsize::new(0);let phase_progress=AtomicUsize::new(0);

 let allocate=|event:crate::native_encoding::NativeAllocationEvent|{let request=match event{crate::native_encoding::NativeAllocationEvent::Quote(request)=>request,_=>return Ok(())};calls.fetch_add(1,Ordering::Relaxed);assert_eq!(request.bytes,text.len());assert_eq!(request.owned_bytes,0);assert_eq!(request.next_owned_bytes,text.len());assert_eq!(request.maximum_bytes,ceiling);Ok(())};
 let mut authority=crate::NativeAllocationAuthority::new(eff::Port(allocate));authority.with_send_loan(&mut (),|allocate_loan|{let mut receipt=crate::native_encoding::NativeForwardedEncodeContinuation::new(ceiling,allocate_loan);assert_eq!(receipt.owned_bytes(),0);assert_eq!(receipt.maximum_bytes(),ceiling);assert_eq!(calls.load(Ordering::Relaxed),0);
 let mut original=|_|{original_progress.fetch_add(1,Ordering::Relaxed);true};let mut canceled=|_|{phase_progress.fetch_add(1,Ordering::Relaxed);false};
 let error=receipt.encode(&mut original,|control|control.scoped_observer(&mut canceled,|scoped|{let mut owned=eff::reserve_text(scoped,text.len())?;owned.push_str(text);Ok::<_,ValueError>(owned)})).map_err(eff::cause).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),0);assert_eq!(calls.load(Ordering::Relaxed),0);assert_eq!(original_progress.load(Ordering::Relaxed),1);assert_eq!(phase_progress.load(Ordering::Relaxed),1);
 let mut phase=|_|{phase_progress.fetch_add(1,Ordering::Relaxed);true};let output=receipt.encode(&mut original,|control|control.scoped_observer(&mut phase,|scoped|{let mut owned=eff::reserve_text(scoped,text.len())?;owned.push_str(text);Ok::<_,ValueError>(owned)})).unwrap();assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value(text).unwrap());assert_eq!(receipt.owned_bytes(),text.len());assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(original_progress.load(Ordering::Relaxed),2);assert_eq!(phase_progress.load(Ordering::Relaxed),2);
 let mut canceled_original=|_|{original_progress.fetch_add(1,Ordering::Relaxed);false};assert_eq!(receipt.encode(&mut canceled_original,|control|control.scoped_observer(&mut phase,|scoped|scoped.checkpoint())).map_err(eff::cause).unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),text.len());assert_eq!(original_progress.load(Ordering::Relaxed),3);assert_eq!(phase_progress.load(Ordering::Relaxed),2);}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn encoder_original_retirement_slot_survives_pause_and_refused_hops(){
 let law=fixture();let bytes=law["wrapperBytes"].as_u64().unwrap()as usize;let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let mut progress=|_|true;let mut receipt=NativeEncodeControl::new(bytes*3,&mut progress).pause().unwrap().with_retirement_recipient(&mut recipient).unwrap();let mut next=|_|true;
 let error=receipt.encode(&mut next,|control|control.with_retirement_owner(bytes,|_|(Err::<(),_>(ValueError::literal(ValueRefusalKind::InvalidValue,"partial owner refused")),None))).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(receipt.owned_bytes(),bytes);
 receipt.encode(&mut next,|control|control.scoped_observer(&mut | _ |true,|child|child.with_retirement_owner(bytes,|_|(Ok::<(),ValueError>(()),None)))).unwrap();assert_eq!(receipt.owned_bytes(),bytes*2);drop(receipt);assert!(!recipient.has_owner());
}

#[test]
fn encoder_refused_partial_owner_returns_to_the_same_original_recipient(){
 use crate::{ErasedSnapshotRetirement,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
 use std::sync::Arc;
 struct Owner{bytes:Option<Vec<u8>>,drops:Arc<AtomicUsize>}
 impl Drop for Owner{fn drop(&mut self){assert!(self.bytes.is_none());self.drops.fetch_add(1,Ordering::Relaxed);}}
 impl ErasedSnapshotRetirement for Owner{
  fn next_demand(&self,_:usize)->Result<crate::RetirementDemand,ValueError>{Ok(crate::RetirementDemand{copy_bytes:if self.bytes.is_some(){std::mem::size_of::<Option<Vec<u8>>>()}else{0},release_bytes:self.bytes.as_ref().map_or(0,Vec::capacity),depth:1,..Default::default()})}
  fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(u64::from(self.bytes.is_some()))}
  fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{let grant=effect.grant();let mut work=0u128;let result=(||->Result<RetainedCloneStep,ValueError>{if grant.maximum_items==0{return Ok(RetainedCloneStep::Progress(Default::default()))}let copy=std::mem::size_of::<Option<Vec<u8>>>();if grant.maximum_copy_bytes<copy{return Ok(RetainedCloneStep::Progress(Default::default()))}let released=self.next_release_byte_demand()?;if released>grant.maximum_release_bytes{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original retained release grant refused"))}if !effect.performed(1)?{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original retained close exceeds its quote"))}work=1;self.bytes.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:copy,released_bytes:released,..Default::default()}))})();crate::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result:result.map_err(Into::into),work})}
  fn terminal_is_empty(&self)->bool{self.bytes.is_none()}
  fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(if self.bytes.is_some(){std::mem::size_of::<Option<Vec<u8>>>()}else{0})}
  fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
  fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.bytes.as_ref().map_or(0,Vec::capacity))}
  fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
 }
 let law=fixture();let payload:Vec<u8>=serde_json::from_value(law["retainedPayload"].clone()).unwrap();let drops=Arc::new(AtomicUsize::new(0));let bytes=std::mem::size_of::<Owner>()+payload.len();let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let mut origin=|_|true;let mut receipt=NativeEncodeControl::new(bytes,&mut origin).pause().unwrap().with_retirement_recipient(&mut recipient).unwrap();let mut progress=|_|true;
 let error=receipt.encode(&mut progress,|control|control.with_retirement_owner(std::mem::size_of::<Owner>(),|control|match control.copy_bytes(&payload){Err(error)=>(Err::<(),_>(error),None),Ok(owned)=>(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original typed construction refused")),Some(Box::new(Owner{bytes:Some(owned),drops:drops.clone()})as Box<dyn ErasedSnapshotRetirement>))})).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(receipt.owned_bytes(),bytes);assert_eq!(drops.load(Ordering::Relaxed),0);drop(receipt);assert!(recipient.has_owner());
 let denied=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let mut retirement_actual=Some(73);let(turn,heap)=eff::observed(denied,1<<20,&mut retirement_actual,|effect|eff::settled(recipient.close_step(effect)));assert_eq!(heap,(0,0));assert_eq!(retirement_actual,Some(73));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(drops.load(Ordering::Relaxed),0);let granted:RetainedCloneGrant=serde_json::from_value(law["retainedCloseGrant"].clone()).unwrap();let header=law["retainedCloseHeaders"].as_array().unwrap().iter().find(|row|row["nativeWordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();assert_eq!(std::mem::size_of::<Option<Vec<u8>>>(),header["optionalByteHeaderBytes"].as_u64().unwrap()as usize);assert_eq!(std::mem::size_of::<Option<Box<dyn ErasedSnapshotRetirement>>>(),header["ownerSlotHeaderBytes"].as_u64().unwrap()as usize);let mut total=RetainedCloneProgress::default();for _ in 0..granted.maximum_items{if recipient.terminal_is_empty(){break}let remaining=RetainedCloneGrant{maximum_items:granted.maximum_items-total.copied_items,maximum_copy_bytes:granted.maximum_copy_bytes-total.copied_bytes,maximum_capacity_bytes:granted.maximum_capacity_bytes-total.retained_capacity_bytes,maximum_release_bytes:granted.maximum_release_bytes-total.released_bytes,maximum_depth:granted.maximum_depth};assert!(recipient.next_copy_byte_demand().unwrap()<=remaining.maximum_copy_bytes);let mut retirement_actual=None;let(turn,heap)=eff::observed(remaining,1<<20,&mut retirement_actual,|effect|eff::settled(recipient.close_step(effect)));let step=turn.result.unwrap();assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(retirement_actual,if heap.0==0{None}else{Some(heap.0)});assert!(step.progress().fits(remaining));total=total.checked_add(step.progress()).unwrap();}assert!(recipient.terminal_is_empty());assert_eq!(total.copied_bytes,(header["optionalByteHeaderBytes"].as_u64().unwrap()+header["ownerSlotCloseCopyBytes"].as_u64().unwrap())as usize);assert_eq!(total.released_bytes,bytes);assert_eq!(drops.load(Ordering::Relaxed),1);
}

#[test]
fn native_consuming_receipt_retains_original_retirement_recipient_across_short_progress_hops(){
 use crate::{retirement::controlled::ControlledRetirement,ErasedSnapshotRetirement};
 let neutral=fixture();let law=&neutral["retainedNative"];let grant:crate::RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();let text=law["copy"].as_str().unwrap();let pointer=text.as_ptr();let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let events=AtomicUsize::new(0);let mut progress=|_|{events.fetch_add(1,Ordering::Relaxed);true};let mut original=NativeEncodeControl::new(law["maximumBytes"].as_u64().unwrap()as usize,&mut progress);original.charge(law["initialBytes"].as_u64().unwrap()as usize).unwrap();let mut receipt=original.pause().unwrap().with_retirement_recipient(&mut recipient).unwrap();let wrapper=std::mem::size_of::<ControlledRetirement<String>>();
 let error=receipt.encode(&mut progress,|control|control.with_retirement_owner(wrapper,|control|match control.copy_text(text){Err(error)=>(Err::<(),_>(error),None),Ok(owned)=>{assert_eq!(serde_json::to_value(&owned).unwrap(),serde_json::to_value(text).unwrap());(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original native checkpoint refuses after physical ownership")),Some(Box::new(ControlledRetirement::new(owned).ok().unwrap())as Box<dyn ErasedSnapshotRetirement>))}})).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);let retained=receipt.owned_bytes();assert_eq!(retained,law["initialBytes"].as_u64().unwrap()as usize+wrapper+text.len());let mut canceled=|_|false;let refused=receipt.encode(&mut canceled,|control|{let mut retirement_actual=None;let result=eff::settled(eff::with_effect(grant,1<<20,&mut retirement_actual,|effect|control.close_retirement_recipient(effect))).result;assert_eq!(retirement_actual,None);Ok::<_,ValueError>(result)}).unwrap();assert_eq!(refused.unwrap_err().primary().unwrap().kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),retained);
 let mut born=0usize;receipt.encode(&mut progress,|control|{while control.has_retirement_owner(){let mut retirement_actual=None;let(turn,heap)=eff::observed(grant,1<<20,&mut retirement_actual,|effect|eff::settled(control.close_retirement_recipient(effect)));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(retirement_actual,if heap.0==0{None}else{Some(heap.0)});born+=p.retained_capacity_bytes;}Ok(())}).unwrap();assert!(receipt.owned_bytes()>retained);assert_eq!(receipt.owned_bytes(),retained+born);assert_eq!(receipt.maximum_bytes(),law["maximumBytes"].as_u64().unwrap()as usize);drop(receipt);assert!(!recipient.has_owner());assert!(events.load(Ordering::Relaxed)>1);assert_eq!(text.as_ptr(),pointer);
}

#[test]
fn native_recipient_binding_refusal_returns_its_original_consuming_receipt(){
 use crate::{retirement::controlled::ControlledRetirement,ErasedSnapshotRetirement};
 let neutral=fixture();let law=&neutral["retainedNative"];let grant:crate::RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();let text=law["copy"].as_str().unwrap();let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let live=std::sync::atomic::AtomicBool::new(true);let mut progress=|_|live.load(Ordering::Relaxed);let mut native=NativeEncodeControl::new(law["maximumBytes"].as_u64().unwrap()as usize,&mut progress);native.charge(law["initialBytes"].as_u64().unwrap()as usize).unwrap();native.install_retirement_recipient(&mut recipient).unwrap();let error=native.with_retirement_owner(std::mem::size_of::<ControlledRetirement<String>>(),|native|{let owned=native.copy_text(text).unwrap();assert_eq!(serde_json::to_value(&owned).unwrap(),serde_json::to_value(text).unwrap());(Err::<(),_>(ValueError::literal(ValueRefusalKind::InvalidValue,"actual checkpoint returns original partial owner")),Some(Box::new(ControlledRetirement::new(owned).ok().unwrap())as Box<dyn ErasedSnapshotRetirement>))}).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);let expected=native.owned_bytes();let continuation=native.pause_with_retirement().unwrap();assert_eq!(continuation.owned_bytes(),expected);let(original,recipient)=continuation.into_parts();assert_eq!(original.owned_bytes(),expected);assert_eq!(original.maximum_bytes(),law["maximumBytes"].as_u64().unwrap()as usize);assert!(recipient.has_owner());let(error,original)=match original.with_retirement_recipient(recipient){Ok(_)=>panic!("occupied original recipient must refuse binding"),Err(refused)=>refused};assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);let mut resumed_progress=|_|live.load(Ordering::Relaxed);let mut native=NativeEncodeControl::resume(original,&mut resumed_progress).unwrap();assert_eq!(native.owned_bytes(),expected);while recipient.has_owner(){native.checkpoint().unwrap();let capacity=recipient.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap();assert!(capacity<=grant.maximum_capacity_bytes);assert!(recipient.next_copy_byte_demand().unwrap()<=grant.maximum_copy_bytes);assert!(recipient.next_release_byte_demand().unwrap()<=grant.maximum_release_bytes);assert!(recipient.next_depth_demand().unwrap()<=grant.maximum_depth);native.charge(capacity).unwrap();let mut retirement_actual=None;let(turn,heap)=eff::observed(grant,1<<20,&mut retirement_actual,|effect|eff::settled(recipient.close_step(effect)));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(retirement_actual,if heap.0==0{None}else{Some(heap.0)});}assert!(native.owned_bytes()>expected);drop(native);assert!(!recipient.has_owner());
}



#[test]
fn original_allocation_ports_retain_both_post_refusals_and_actual_backing(){
 use crate::native_encoding::NativeAllocationEvent;let mut first_pending=None;let mut second_pending=None;let mut first_bytes=0usize;let mut second_bytes=0usize;let first=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(request)=>{assert!(first_pending.replace(request).is_none());Ok(())},NativeAllocationEvent::Post{request,actual}=>{assert_eq!(first_pending.take(),Some(request));first_bytes+=actual;Err(ValueError::literal(ValueRefusalKind::Canceled,"forwarded post refused"))},NativeAllocationEvent::Cancel(request)=>{assert_eq!(first_pending.take(),Some(request));Ok(())}};let second=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(request)=>{assert!(second_pending.replace(request).is_none());Ok(())},NativeAllocationEvent::Post{request,actual}=>{assert_eq!(second_pending.take(),Some(request));second_bytes+=actual;Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"scoped post refused"))},NativeAllocationEvent::Cancel(request)=>{assert_eq!(second_pending.take(),Some(request));Ok(())}};let mut observe=|_|true;let mut output=None;let mut first_authority=crate::NativeAllocationAuthority::new(eff::Port(first));let mut second_authority=crate::NativeAllocationAuthority::new(eff::Port(second));let result=first_authority.with_send_loan(&mut (),|first_loan|second_authority.with_send_loan(&mut (),|second_loan|{let mut native=NativeEncodeControl::new_forwarded(16,&mut observe,first_loan);native.scoped_allocation=Some(second_loan);let mut actual=None;let mut unwind=None;let result=native.allocate_effect(16,&mut actual,&mut unwind,&mut |actual:&mut Option<usize>,_|{let layout=std::alloc::Layout::array::<u64>(2).unwrap();let pointer=unsafe{std::alloc::alloc(layout)}.cast::<u64>();if pointer.is_null(){return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))}output=Some(unsafe{Vec::from_raw_parts(pointer,0,2)});*actual=Some(layout.size());Err(ValueError::literal(ValueRefusalKind::InvalidValue,"operation refused after allocation"))}).unwrap().expect("original allocation settled");assert_eq!(native.owned_bytes(),16);assert_eq!(result.actual,Some(16));assert_eq!(result.forwarded_refusal.as_ref().unwrap().owned().unwrap().message.as_ref(),"forwarded post refused");assert_eq!(result.scoped_refusal.as_ref().unwrap().owned().unwrap().message.as_ref(),"scoped post refused");assert_eq!(result.primary.as_ref().unwrap().message.as_ref(),"operation refused after allocation");assert!(result.extent_refusal.is_none());assert!(unwind.is_none());native.scoped_allocation=None;drop(native);result}).unwrap()).unwrap();assert!(first_authority.into_port().is_ok());assert!(second_authority.into_port().is_ok());assert_eq!((first_bytes,second_bytes),(16,16));assert!(first_pending.is_none()&&second_pending.is_none());eff::close(output.take().unwrap());eff::close(result);
}

#[test]
fn partial_allocation_keeps_requested_admission_and_actual_capacity_distinct(){
 use crate::native_encoding::NativeAllocationEvent;let mut pending=None;let mut submitted=0usize;let mut admitted=0usize;let mut quotes=0;let port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(request)=>{assert_eq!(request.owned_bytes,admitted);assert!(pending.replace(request).is_none());quotes+=1;Ok(())},NativeAllocationEvent::Post{request,actual}=>{assert_eq!(pending.take(),Some(request));submitted+=actual;admitted=request.next_owned_bytes;Ok(())},NativeAllocationEvent::Cancel(request)=>{assert_eq!(pending.take(),Some(request));Ok(())}};let mut observe=|_|true;let mut output=None;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(port));let(first,second)=authority.with_send_loan(&mut (),|port_loan|{let mut native=NativeEncodeControl::new_forwarded(32,&mut observe,port_loan);let mut actual=None;let mut unwind=None;let first=native.allocate_effect(16,&mut actual,&mut unwind,&mut |actual:&mut Option<usize>,_|{let layout=std::alloc::Layout::array::<u8>(8).unwrap();let pointer=unsafe{std::alloc::alloc(layout)};if pointer.is_null(){return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))}output=Some(unsafe{Vec::from_raw_parts(pointer,0,8)});*actual=Some(8);Ok(true)}).unwrap().expect("original allocation settled");assert!(first.primary.is_none()&&first.extent_refusal.is_none()&&first.forwarded_refusal.is_none());assert_eq!(first.request.unwrap().bytes,16);assert_eq!(first.actual,Some(8));assert_eq!(native.owned_bytes(),16);actual=None;let second=native.allocate_effect(16,&mut actual,&mut unwind,&mut |_,_|Err(ValueError::literal(ValueRefusalKind::Canceled,"no effect"))).unwrap().expect("original allocation settled");assert_eq!(native.owned_bytes(),16);drop(native);(first,second)}).unwrap();assert!(authority.into_port().is_ok());assert_eq!(submitted,8);assert_eq!(quotes,2);assert!(pending.is_none());for error in [first,second]{eff::close(error);}eff::close(output.take().unwrap());
}


#[test]fn refused_second_allocation_quote_cancels_first_original_quote(){use crate::native_encoding::NativeAllocationEvent;let mut pending=None;let mut canceled=0;let mut called=false;let first=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(request)=>{assert!(pending.replace(request).is_none());Ok(())},NativeAllocationEvent::Cancel(request)=>{assert_eq!(pending.take(),Some(request));canceled+=1;Ok(())},NativeAllocationEvent::Post{..}=>panic!("second quote failed")};let second=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"scoped quote refused")),_=>panic!("refused quote has no settlement")};let mut observe=|_|true;let mut first_authority=crate::NativeAllocationAuthority::new(eff::Port(first));let mut second_authority=crate::NativeAllocationAuthority::new(eff::Port(second));let outcome=first_authority.with_send_loan(&mut (),|first_loan|second_authority.with_send_loan(&mut (),|second_loan|{let mut native=NativeEncodeControl::new_forwarded(16,&mut observe,first_loan);native.scoped_allocation=Some(second_loan);let mut actual=None;let mut unwind=None;let outcome=native.allocate_effect(16,&mut actual,&mut unwind,&mut |_,_|{called=true;Ok(true)}).unwrap().expect("original allocation settled");assert_eq!(outcome.scoped_quote.as_ref().unwrap().owned().unwrap().message.as_ref(),"scoped quote refused");assert!(outcome.primary.is_none());assert!(outcome.forwarded_refusal.is_none());assert_eq!(native.owned_bytes(),0);native.scoped_allocation=None;drop(native);outcome}).unwrap()).unwrap();assert!(first_authority.into_port().is_ok());assert!(second_authority.into_port().is_ok());assert!(!called);assert_eq!(canceled,1);assert!(pending.is_none());eff::close(outcome);}

#[test]fn refused_second_quote_retains_first_cancel_refusal(){use crate::native_encoding::NativeAllocationEvent;let mut pending=None;let mut canceled=0;let mut called=false;let first=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(request)=>{assert!(pending.replace(request).is_none());Ok(())},NativeAllocationEvent::Cancel(request)=>{assert_eq!(pending.take(),Some(request));canceled+=1;Err(ValueError::literal(ValueRefusalKind::Canceled,"first cancel refused"))},NativeAllocationEvent::Post{..}=>panic!("second quote failed")};let second=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected budget admission"),NativeAllocationEvent::Quote(_)=>Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"scoped quote refused")),_=>panic!("refused quote has no settlement")};let mut observe=|_|true;let mut first_authority=crate::NativeAllocationAuthority::new(eff::Port(first));let mut second_authority=crate::NativeAllocationAuthority::new(eff::Port(second));let outcome=first_authority.with_send_loan(&mut (),|first_loan|second_authority.with_send_loan(&mut (),|second_loan|{let mut native=NativeEncodeControl::new_forwarded(16,&mut observe,first_loan);native.scoped_allocation=Some(second_loan);let mut actual=None;let mut unwind=None;let outcome=native.allocate_effect(16,&mut actual,&mut unwind,&mut |_,_|{called=true;Ok(true)}).unwrap().expect("original allocation settled");assert_eq!(outcome.scoped_quote.as_ref().unwrap().owned().unwrap().message.as_ref(),"scoped quote refused");assert!(outcome.primary.is_none());assert_eq!(outcome.forwarded_refusal.as_ref().unwrap().owned().unwrap().message.as_ref(),"first cancel refused");assert_eq!(native.owned_bytes(),0);native.scoped_allocation=None;drop(native);outcome}).unwrap()).unwrap();assert!(first_authority.into_port().is_ok());assert!(second_authority.into_port().is_ok());assert!(!called);assert_eq!(canceled,1);assert!(pending.is_none());eff::close(outcome);}


#[test]fn outcome_slot_retains_refusal_before_the_next_action(){let rows:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🛂️allocation/🧪️tests/🧾️outcome-slot.json")).unwrap();let mut observer=|_|true;let mut control=NativeEncodeControl::new(8,&mut observer);let mut actual=None;let mut progress=None;let mut outcome=None;let mut calls=0;control.allocate_effect_into(1,&mut actual,&mut progress,&mut outcome,&mut |_,_|{calls+=1;Err(ValueError::literal(ValueRefusalKind::Canceled,"original operation refused"))}).unwrap();assert_eq!(calls,rows[1]["called"].as_u64().unwrap()as usize);assert_eq!(outcome.as_ref().unwrap().primary.as_ref().unwrap().message.as_ref(),"original operation refused");let refusal=control.allocate_effect_into(1,&mut actual,&mut progress,&mut outcome,&mut |_,_|{calls+=1;Ok(true)}).unwrap_err();assert_eq!(calls,1);assert_eq!(outcome.as_ref().unwrap().primary.as_ref().unwrap().message.as_ref(),"original operation refused");eff::close(outcome.take().unwrap());eff::close(refusal);let mut storage=None;control.allocate_effect_into(1,&mut actual,&mut progress,&mut outcome,&mut |actual:&mut Option<usize>,_|{let layout=std::alloc::Layout::array::<u8>(1).unwrap();let pointer=unsafe{std::alloc::alloc(layout)};if pointer.is_null(){return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))}storage=Some(unsafe{Vec::from_raw_parts(pointer,0,1)});*actual=Some(1);Ok(true)}).unwrap();assert!(outcome.as_ref().unwrap().admitted);assert_eq!(outcome.as_ref().unwrap().actual,Some(1));assert_eq!(rows[0]["retained"],true);eff::close(outcome.take().unwrap());eff::close(storage.take().unwrap());}

#[test]
fn forwarded_encode_restores_original_receipt_after_unwind(){
 let mut authority=crate::NativeAllocationAuthority::new(eff::Port(|_|Ok(())));authority.with_send_loan(&mut (),|loan|{let mut source=crate::native_encoding::NativeForwardedEncodeContinuation::new(64,loan);let mut observe=|_|true;let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _:Result<(),semio_framework_value_call::NativeCallFailure<(),ValueError>>=source.encode(&mut observe,|_|panic!("original forwarded child interrupted"));}));assert!(interrupted.is_err());assert_eq!(source.owned_bytes(),0);let value=source.encode(&mut observe,|_|Ok::<_,ValueError>(37)).unwrap();assert_eq!(value,37);}).unwrap();assert!(authority.into_port().is_ok());
}
#[test]
fn forwarded_owned_storage_requires_the_quoted_effect(){
 let calls=AtomicUsize::new(0);let allocate=|_:crate::native_encoding::NativeAllocationEvent|{calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut progress=|_|true;let mut authority=crate::NativeAllocationAuthority::new(eff::Port(allocate));
 authority.with_send_loan(&mut (),|loan|{let mut control=NativeEncodeControl::new_forwarded(64,&mut progress,loan);assert_eq!(control.charge(1).unwrap_err().kind,ValueRefusalKind::UnsupportedOwner);assert_eq!(control.copy_text("x").unwrap_err().kind,ValueRefusalKind::UnsupportedOwner);assert_eq!(control.owned_bytes(),0);}).unwrap();
 assert!(authority.into_port().is_ok());assert_eq!(calls.load(Ordering::Relaxed),0);
}
